function dataset = carsim_collect_dataset(manifest, outCsv, options)
%CARSIM_COLLECT_DATASET Run real CarSim/Simulink co-simulations to CSV.
%
% The model must have been generated by create_carsim_brake_cosim_model.
% Required manifest columns:
%   case_id, initial_speed_kph, mu, pressure_seed, stop_time_s, run_file

arguments
    manifest
    outCsv (1,1) string = fullfile("data", "carsim_brake_sequence_dataset.csv")
    options.ModelPath (1,1) string = ""
    options.RunFileDialogParameter (1,1) string = ""
    options.FailOnSpeedMismatch (1,1) logical = true
    options.SaveRawOutputs (1,1) logical = false
end

projectRoot = fileparts(fileparts(mfilename("fullpath")));
cfg = defaultCarSimConfig(projectRoot);
if strlength(options.ModelPath) > 0
    cfg.modelPath = options.ModelPath;
    [~, cfg.modelName] = fileparts(options.ModelPath);
    cfg.carSimBlockPath = cfg.modelName + "/CarSimVehicle";
end
if strlength(options.RunFileDialogParameter) > 0
    cfg.runFileDialogParameter = options.RunFileDialogParameter;
end

cases = readManifest(manifest);
validateManifest(cases);
if ~isfile(cfg.modelPath)
    error("CarSim:MissingModel", ...
        "Co-simulation model not found: %s. Run create_carsim_brake_cosim_model first.", ...
        cfg.modelPath);
end

load_system(cfg.modelPath);
cleanup = onCleanup(@() closeIfNeeded(cfg.modelName));
tables = cell(height(cases), 1);
rawOutputs = cell(height(cases), 1);

for i = 1:height(cases)
    row = cases(i, :);
    profile = makePressureProfile(row.stop_time_s, row.pressure_seed, cfg);

    simIn = Simulink.SimulationInput(cfg.modelName);
    simIn = simIn.setVariable("case_pressure_profile", ...
        timeseries(profile.pressure_MPa, profile.time_s));
    simIn = simIn.setVariable("case_mu", row.mu);
    simIn = simIn.setVariable("case_stop_time", row.stop_time_s);
    simIn = simIn.setModelParameter( ...
        "StopTime", num2str(row.stop_time_s, "%.9g"));

    runFile = string(row.run_file);
    if ismissing(runFile)
        runFile = "";
    end
    if strlength(runFile) > 0
        if strlength(cfg.runFileDialogParameter) == 0
            error("CarSim:RunParameterUnknown", ...
                "Manifest contains run_file, but RunFileDialogParameter is empty. " + ...
                "Run inspect_carsim_interface and pass the matching dialog parameter.");
        end
        if ~isfile(runFile)
            error("CarSim:MissingRunFile", ...
                "CarSim run file not found for case %d: %s", row.case_id, runFile);
        end
        simIn = simIn.setBlockParameter(cfg.carSimBlockPath, ...
            cfg.runFileDialogParameter, runFile);
    end

    fprintf("CarSim case %d/%d: %.1f km/h, mu=%.2f\n", ...
        i, height(cases), row.initial_speed_kph, row.mu);
    simOut = sim(simIn);
    tables{i} = extractTrajectoryTable(simOut, row, cfg, ...
        options.FailOnSpeedMismatch);
    if options.SaveRawOutputs
        rawOutputs{i} = simOut;
    end
end

dataset = vertcat(tables{:});
outDir = fileparts(outCsv);
if strlength(outDir) > 0 && ~isfolder(outDir)
    mkdir(outDir);
end
writetable(dataset, outCsv);

metadata = struct();
metadata.generatedAt = datetime("now");
metadata.modelPath = cfg.modelPath;
metadata.config = cfg;
metadata.manifest = cases;
metadataPath = fullfile(outDir, "carsim_dataset_metadata.mat");
save(metadataPath, "metadata");
if options.SaveRawOutputs
    rawPath = fullfile(outDir, "carsim_raw_outputs.mat");
    save(rawPath, ...
        "rawOutputs", "-v7.3");
end
fprintf("Saved %d CarSim transitions: %s\n", height(dataset), outCsv);
end

function cases = readManifest(manifest)
if istable(manifest)
    cases = manifest;
elseif isstring(manifest) || ischar(manifest)
    if ~isfile(manifest)
        error("CarSim:MissingManifest", "Manifest not found: %s", manifest);
    end
    cases = readtable(manifest, "TextType", "string");
else
    error("CarSim:InvalidManifest", ...
        "manifest must be a table or CSV path.");
end
end

function validateManifest(cases)
required = ["case_id", "initial_speed_kph", "mu", ...
    "pressure_seed", "stop_time_s", "run_file"];
missing = setdiff(required, string(cases.Properties.VariableNames));
if ~isempty(missing)
    error("CarSim:ManifestColumns", ...
        "Manifest is missing columns: %s", strjoin(missing, ", "));
end
if any(cases.initial_speed_kph <= 0)
    error("CarSim:ManifestSpeed", "Initial speeds must be positive.");
end
if any(cases.mu <= 0 | cases.mu > 1.2)
    error("CarSim:ManifestMu", "mu values must be in (0, 1.2].");
end
if any(cases.stop_time_s <= 0)
    error("CarSim:ManifestTime", "stop_time_s must be positive.");
end
end

function profile = makePressureProfile(stopTimeS, seed, cfg)
rng(seed);
t = (0:cfg.datasetStepS:stopTimeS)';
pressure = zeros(size(t));
target = cfg.pressureMaxMPa * rand();
segmentLeft = randi([8, 30]);
for k = 2:numel(t)
    segmentLeft = segmentLeft - 1;
    if segmentLeft <= 0
        target = cfg.pressureMaxMPa * rand();
        segmentLeft = randi([8, 30]);
    end
    pressure(k) = min(max(0.86 * pressure(k - 1) + ...
        0.14 * target + 0.20 * randn(), ...
        cfg.pressureMinMPa), cfg.pressureMaxMPa);
end
profile = table(t, pressure, ...
    "VariableNames", {"time_s", "pressure_MPa"});
end

function tbl = extractTrajectoryTable(simOut, caseRow, cfg, failOnMismatch)
vSig = outputTimeseries(simOut, "v_carsim_ts");
aSig = outputTimeseries(simOut, "a_carsim_ts");
pSig = outputTimeseries(simOut, "pressure_command_ts");

tEnd = min([vSig.Time(end), aSig.Time(end), pSig.Time(end), ...
    caseRow.stop_time_s]);
t = (0:cfg.datasetStepS:tEnd)';
v = interp1(vSig.Time(:), squeeze(vSig.Data), t, "linear", "extrap");
a = interp1(aSig.Time(:), squeeze(aSig.Data), t, "linear", "extrap");
pressure = interp1(pSig.Time(:), squeeze(pSig.Data), t, "previous", "extrap");

v = v(:);
a = a(:);
pressure = pressure(:);
valid = isfinite(t) & isfinite(v) & isfinite(a) & isfinite(pressure);
t = t(valid);
v = v(valid);
a = a(valid);
pressure = pressure(valid);

if numel(t) < 2
    error("CarSim:ShortOutput", ...
        "Case %d returned fewer than two valid samples.", caseRow.case_id);
end

observedKph = v(1) * 3.6;
speedError = abs(observedKph - caseRow.initial_speed_kph);
if speedError > cfg.initialSpeedToleranceKph
    format = "Case %d manifest speed is %.1f km/h, but CarSim starts at %.1f km/h. " + ...
        "The selected Run dataset or run-file mask parameter is incorrect.";
    message = sprintf(format, ...
        caseRow.case_id, caseRow.initial_speed_kph, observedKph);
    if failOnMismatch
        error("CarSim:SpeedMismatch", "%s", message);
    else
        warning("CarSim:SpeedMismatch", "%s", message);
    end
end

n = numel(t) - 1;
trajectory_id = repmat(caseRow.case_id, n, 1);
step = (0:n-1)';
time_s = t(1:n);
v_mps = v(1:n);
a_mps2 = a(1:n);
pressure_MPa = pressure(1:n);
mu = repmat(caseRow.mu, n, 1);
v_next_mps = v(2:n+1);
a_next_mps2 = a(2:n+1);
initial_speed_kph = repmat(caseRow.initial_speed_kph, n, 1);
source = repmat("CarSim", n, 1);

fRequested = cfg.referenceBrakeGainNPerMPa * pressure_MPa;
fLimit = mu * cfg.massKg * cfg.gravityMps2;
brake_utilization_reference = fRequested ./ max(fLimit, eps);
slip_risk_reference = brake_utilization_reference > 0.95;

tbl = table(trajectory_id, step, time_s, v_mps, a_mps2, ...
    pressure_MPa, mu, v_next_mps, a_next_mps2, ...
    initial_speed_kph, brake_utilization_reference, ...
    slip_risk_reference, source);
end

function ts = outputTimeseries(simOut, name)
available = string(who(simOut));
if ~any(available == name)
    error("CarSim:MissingOutput", ...
        "Simulation output '%s' is missing. Rebuild the co-simulation model.", name);
end
ts = simOut.get(name);
if ~isa(ts, "timeseries")
    error("CarSim:OutputType", ...
        "Simulation output '%s' is not a timeseries.", name);
end
end

function closeIfNeeded(modelName)
if bdIsLoaded(modelName)
    close_system(modelName, 0);
end
end
